 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    marked = set()
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != background:
            marked.update((r, c) for c in range(w))
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if len(set(col)) == 1 and col[0] != background:
            marked.update((r, c) for r in range(h))
    return [[2 if (r, c) in marked else grid[r][c] for c in range(w)] for r in range(h)]
